//! Runs of makeblastdb 2.17.0 (Linux x86-64) for the tests of `-logfile`, of several `-in`
//! files and of the metadata file of version 5: the exit status, the two output streams, the
//! log file and the files of the output directory (bytes, or the size and FNV-1a digest of
//! a file over 4096 bytes).
//!
//! Generated (`pr1/fix/gen_v5_cases.py` of the makedb-v5 line's task folder, makeblastdb run
//! from `LOSAT/` with the input names below); do not edit by hand. `<D>` is the output
//! directory, `<T>` the build time and `<S>` the seconds of the timed line.

/// A file of the output directory.
pub(super) enum Expected {
    Bytes(&'static [u8]),
    /// Size and FNV-1a digest.
    Digest(usize, u64),
}

/// One run of makeblastdb.
pub(super) struct V5Run {
    pub words: &'static [&'static str],
    pub status: i32,
    pub stdout: &'static [u8],
    pub stderr: &'static [u8],
}

/// One case: its runs in one output directory, then what the directory holds.
pub(super) struct V5Case {
    pub name: &'static str,
    pub runs: &'static [V5Run],
    /// The date stored in the database; empty when none was written.
    pub date: &'static str,
    /// The `-logfile` file `<D>/mk.log`, when one was written.
    pub log: Option<&'static [u8]>,
    /// The files of `<D>` but `mk.log`, sorted by name.
    pub files: &'static [(&'static str, Expected)],
}

